-- External feed register (MASTER_SPEC Part 5 section 2). Re-runnable. Counts are filled by scripts/feeds_status.py from the real tables.
SET client_min_messages = warning;
DROP TABLE IF EXISTS core.feeds;
CREATE TABLE core.feeds (
  id serial PRIMARY KEY, feed text NOT NULL UNIQUE, purpose text, cost_licence text, needed_by text, plug_in_point text, without_it text,
  status text NOT NULL CHECK (status IN ('live','manual','pending_licence','pending_purchase','blocked','not_started')),
  count_sql text, last_refresh date, blocked_reason text, next_action text, updated date NOT NULL DEFAULT current_date);
GRANT SELECT ON core.feeds TO ai_readonly;
